<?php
require_once __DIR__.'/_data.php';$db=storefront_db();$customer=$db?marketplace_customer($db):null;if(!$customer)legacy_redirect('masuk?next=wishlist');$cid=(int)$customer['id'];
$weightExpr=marketplace_column_exists($db,'products','weight_gram')?'p.weight_gram':((string)marketplace_default_weight());$stmt=$db->prepare("SELECT p.id,p.category_id,p.product_code,p.name,p.description,p.image,p.selling_price,p.stock,p.unit,{$weightExpr} weight_gram,c.name category_name,c.slug category_slug,COALESCE(pbs.stock,CASE WHEN b.is_main=1 THEN p.stock ELSE 0 END,0) stock_total FROM marketplace_wishlists w JOIN products p ON p.id=w.product_id LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN branches b ON b.id=? LEFT JOIN product_branch_stocks pbs ON pbs.product_id=p.id AND pbs.branch_id=b.id WHERE w.customer_id=? AND p.is_active=1 ORDER BY w.id DESC");$stmt->execute([marketplace_branch_id($db),$cid]);$products=$stmt->fetchAll()?:[];foreach($products as &$wp){$wp['weight_gram']=marketplace_v15_product_weight($db,(int)$wp['id'],(int)($wp['weight_gram']??marketplace_default_weight()));}unset($wp);$wishlistIds=array_map(fn($p)=>(int)$p['id'],$products);$pageTitle='Wishlist';$activePage='account';require __DIR__.'/_header.php';
?>
<main class="inner-page"><section class="store-container page-hero small"><div><span class="hero-label"><i class="bi bi-heart-fill"></i> FAVORIT SAYA</span><h1>Wishlist <span>Produk</span></h1><p>Simpan produk favorit dan masukkan ke keranjang kapan saja.</p></div><div class="page-hero-icon"><i class="bi bi-bag-heart-fill"></i></div></section><section class="store-container catalog-content"><div class="catalog-result-head"><div><span class="eyebrow">WISHLIST</span><h2><?=count($products)?> Produk tersimpan</h2></div><a class="btn-soft" href="<?=legacy_base_url('akun')?>"><i class="bi bi-arrow-left"></i> Akun Saya</a></div><div class="product-grid catalog-grid"><?php if($products):foreach($products as $product):$img=storefront_product_image($product);$fallback=storefront_product_fallback($product);$stock=(int)$product['stock_total'];?><article class="product-card"><div class="product-media"><button class="wish-btn active" type="button" data-product-id="<?=$product['id']?>"><i class="bi bi-heart-fill"></i></button><a href="<?=e(storefront_product_url($product))?>"><img src="<?=e($img)?>" data-fallback="<?=e($fallback)?>" onerror="this.onerror=null;this.src=this.dataset.fallback" alt="<?=e($product['name'])?>"></a></div><div class="product-info"><span class="product-category"><?=e($product['category_name']?:'Produk')?></span><h3><a class="product-title-link" href="<?=e(storefront_product_url($product))?>"><?=e($product['name'])?></a></h3><div class="product-bottom"><div><strong><?=rupiah($product['selling_price'])?></strong><span class="stock-badge <?=$stock<=0?'out':''?>"><?=$stock>0?'Stok '.$stock:'Habis'?></span></div><button class="add-cart-btn" type="button" data-product="<?=storefront_product_json($product)?>" <?=$stock<=0?'disabled':''?>><i class="bi bi-plus-lg"></i><span>Keranjang</span></button></div></div></article><?php endforeach;else:?><div class="empty-products full-span"><i class="bi bi-heart"></i><h3>Wishlist masih kosong</h3><p>Tekan ikon hati pada produk yang ingin disimpan.</p><a class="btn-primary-store" href="<?=legacy_base_url('produk')?>">Cari Produk</a></div><?php endif;?></div></section></main>
